syntax:
SELECT …
FROM таблица
WHERE условие1 AND (условие2 OR условие3);

SELECT …
FROM таблица
WHERE столбец IN (значение1, значение2, значение3);

example:
SELECT id, plate, make, color, owner_name
FROM vehicles
WHERE plate IN ('К404ТО', 'О114РБ');

syntax:
SELECT …
FROM таблица
WHERE столбец BETWEEN нижняя_граница AND верхняя_граница;

SELECT …
FROM таблица
WHERE столбец LIKE '%часть%';

example:
SELECT id, plate, make, model
FROM vehicles
WHERE make LIKE '%тайга%';

syntax:
SELECT …
FROM таблица
WHERE столбец IS NULL;

-- и наоборот:
WHERE столбец IS NOT NULL;

SELECT DISTINCT столбец1, столбец2
FROM таблица
WHERE …;

example:
SELECT DISTINCT district
FROM incidents
WHERE kind = 'угон';
